325	    /**
326	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
327	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
328	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
329	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
330	     * longer any per-city sequence number.
331	     *
332	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
333	     * @return the generated customer code
334	     */
335	    private String generateCustomerCode(Owner owner) {
336	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
337	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
338	        return region + "-" + hash8;
339	    }
340	
341	    /**
342	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
343	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
344	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
345	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
346	     * known region.
347	     *
348	     * @param postcode the owner's postcode, may be {@code null}
349	     * @param city     the owner's city
350	     * @return the derived region code
351	     */
352	    private String deriveRegion(String postcode, String city) {
353	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
354	            int value = Integer.parseInt(postcode);
355	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
356	                int[] range = entry.getValue();
357	                if (value >= range[0] && value <= range[1]) {
358	                    return entry.getKey();
359	                }
360	            }
361	        }
362	        String region = CITY_REGION.get(city);
363	        return region != null ? region : "UNKNOWN";
364	    }
365	
366	    /**
367	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
368	     * bytes of {@code input}.
369	     *
370	     * @param input  the value to digest
371	     * @param length the number of leading hex characters to return
372	     * @return the truncated upper-case hex digest
373	     */
374	    private String shortSha256Hex(String input, int length) {
375	        try {
376	            byte[] digest = MessageDigest.getInstance("SHA-256")
377	                .digest(input.getBytes(StandardCharsets.UTF_8));
378	            StringBuilder sb = new StringBuilder(digest.length * 2);
379	            for (byte b : digest) {
380	                sb.append(String.format("%02x", b));
381	            }
382	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
383	        } catch (java.security.NoSuchAlgorithmException e) {
384	            throw new IllegalStateException("SHA-256 not available", e);
385	        }
386	    }
