388	    /**
389	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
390	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
391	     * that is stored, returned and used for every value derived from it.
392	     *
393	     * @param date the effective registration date (supplied or defaulted)
394	     * @return the same date when it is a weekday, otherwise the next Monday
395	     */
396	    private LocalDate rollToBusinessDay(LocalDate date) {
397	        DayOfWeek dayOfWeek = date.getDayOfWeek();
398	        if (dayOfWeek == DayOfWeek.SATURDAY) {
399	            return date.plusDays(2);
400	        }
401	        if (dayOfWeek == DayOfWeek.SUNDAY) {
402	            return date.plusDays(1);
403	        }
404	        return date;
405	    }
