407	    /**
408	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
409	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
410	     *
411	     * @param customerCode     the owner's already-assigned customer code
412	     * @param registrationDate the owner's registration date
413	     * @return the generated membership number
414	     */
415	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
416	        String yy = String.format("%02d", registrationDate.getYear() % 100);
417	        return String.format("%s-M%s", customerCode, yy);
418	    }
