465	    /**
466	     * Find the existing owners that live in the same household as the given values, i.e. those that
467	     * share both the last name and the address when each is compared case-insensitively with
468	     * collapsed whitespace.
469	     *
470	     * @param lastName the incoming owner's last name
471	     * @param address  the incoming owner's address
472	     * @return the matching existing owners (possibly empty)
473	     */
474	    private List<Owner> findHouseholdMembers(String lastName, String address) {
475	        String normalizedLastName = normalizeForComparison(lastName);
476	        String normalizedAddress = normalizeForComparison(address);
477	        return this.clinicService.findAllOwners().stream()
478	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
479	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
480	            .toList();
