483	    /**
484	     * Generate a stable shared household identifier for the given last name and address. The value is
485	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
486	     * and address, so every owner joining the same household resolves to the same identifier. It is the
487	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
488	     *
489	     * @param lastName the household's last name
490	     * @param address  the household's address
491	     * @return the stable household identifier
492	     */
493	    private String generateHouseholdId(String lastName, String address) {
494	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
495	        return shortSha256Hex(key, 12);
496	    }
