498	    /**
499	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
500	     * single space, upper-case the result and expand common street-type abbreviations token by token
501	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
502	     * to the empty string. The result is the canonical form that is stored, returned and used for every
503	     * address comparison (household duplicate detection and the shared household id).
504	     *
505	     * @param address the raw address, may be {@code null}
506	     * @return the normalized address
507	     */
508	    private String normalizeAddress(String address) {
509	        if (address == null) {
510	            return "";
511	        }
512	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
513	        if (collapsed.isEmpty()) {
514	            return "";
515	        }
516	        String[] tokens = collapsed.split(" ");
517	        StringBuilder sb = new StringBuilder(collapsed.length());
518	        for (int i = 0; i < tokens.length; i++) {
519	            if (i > 0) {
520	                sb.append(' ');
521	            }
522	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
523	        }
524	        return sb.toString();
525	    }
