527	    /**
528	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
529	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
530	     *
531	     * @param value the raw value, may be {@code null}
532	     * @return the normalized value
533	     */
534	    private String normalizeForComparison(String value) {
535	        if (value == null) {
536	            return "";
537	        }
538	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
539	    }
