541	    /**
542	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
543	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
544	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
545	     * is returned lower-cased.
546	     *
547	     * @param email the raw email from the request payload, may be {@code null}
548	     * @return the lower-cased email, or {@code null} when none was provided
549	     */
550	    private String normalizeEmail(String email) {
551	        if (!StringUtils.hasText(email)) {
552	            return null;
553	        }
554	        if (!EMAIL_PATTERN.matcher(email).matches()) {
555	            throw new InvalidRequestException(List.of("email"));
556	        }
557	        return email.toLowerCase(Locale.ROOT);
558	    }
