560	    /**
561	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
562	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
563	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
564	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
565	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
566	     * to 400 Bad Request).
567	     *
568	     * @param city     the owner's city (used to resolve the region)
569	     * @param postcode the raw postcode from the request payload, may be {@code null}
570	     */
571	    private void validatePostcode(String city, String postcode) {
572	        if (!StringUtils.hasText(postcode)) {
573	            return;
574	        }
575	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
576	            throw new InvalidRequestException(List.of("postcode"));
577	        }
578	        String region = CITY_REGION.get(city);
579	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
580	        if (range != null) {
581	            int value = Integer.parseInt(postcode);
582	            if (value < range[0] || value > range[1]) {
583	                throw new InvalidRequestException(List.of("postcode"));
584	            }
585	        }
586	    }
