588	    /**
589	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
590	     * already carries a leading '+' keeps its country code; otherwise the default country code
591	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
592	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
593	     * is thrown (mapped to 400 Bad Request).
594	     *
595	     * @param telephone the raw telephone from the request payload
596	     * @return the E.164 string (e.g. {@code +61412345678})
597	     */
598	    private String normalizeTelephone(String telephone) {
599	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
600	        String candidate;
601	        if (cleaned.startsWith("+")) {
602	            candidate = cleaned;
603	        } else {
604	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
605	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
606	        }
607	        if (!E164_PATTERN.matcher(candidate).matches()) {
608	            throw new InvalidRequestException(List.of("telephone"));
609	        }
610	        // For country codes with a known fixed national-number length, reject a candidate whose
611	        // national digits (everything after the '+' and the country code) do not match that length.
612	        String digits = candidate.substring(1);
613	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
614	            String countryCode = entry.getKey();
615	            if (digits.startsWith(countryCode)) {
616	                int nationalLength = digits.length() - countryCode.length();
617	                if (nationalLength != entry.getValue()) {
618	                    throw new InvalidRequestException(List.of("telephone"));
619	                }
620	                break;
621	            }
622	        }
623	        return candidate;
624	    }
