627	    @Transactional
628	    @Override
629	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
630	        Owner owner = this.clinicService.findOwnerById(ownerId);
631	        if (owner == null) {
632	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
633	        }
634	        this.clinicService.deleteOwner(owner);
635	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
636	    }
637	
638	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
639	    @Override
640	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
641	        Owner owner = this.clinicService.findOwnerById(ownerId);
642	        if (owner == null) {
643	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
644	        }
645	        HttpHeaders headers = new HttpHeaders();
646	        Pet pet = petMapper.toPet(petFieldsDto);
647	        owner.setId(ownerId);
648	        pet.setOwner(owner);
649	        pet.getType().setName(null);
650	        this.clinicService.savePet(pet);
651	        PetDto petDto = petMapper.toPetDto(pet);
652	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
653	            .buildAndExpand(pet.getId()).toUri());
654	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
655	    }
656	
657	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
658	    @Override
659	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
660	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
661	        if (currentOwner != null) {
662	            Pet currentPet = this.clinicService.findPetById(petId);
663	            if (currentPet != null) {
664	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
665	                currentPet.setName(petFieldsDto.getName());
666	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
667	                this.clinicService.savePet(currentPet);
668	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
669	            }
670	        }
671	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
672	    }
673	
674	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
675	    @Override
676	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
677	        HttpHeaders headers = new HttpHeaders();
678	        Visit visit = visitMapper.toVisit(visitFieldsDto);
679	        Pet pet = new Pet();
680	        pet.setId(petId);
681	        visit.setPet(pet);
682	        this.clinicService.saveVisit(visit);
683	        VisitDto visitDto = visitMapper.toVisitDto(visit);
684	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
685	            .buildAndExpand(visit.getId()).toUri());
686	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
687	    }
688	
689	
690	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
691	    @Override
692	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
693	        Owner owner = this.clinicService.findOwnerById(ownerId);
694	        if (owner != null) {
695	            Pet pet = owner.getPet(petId);
696	            if (pet != null) {
697	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
698	            }
699	        }
700	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
701	    }
